div.script:

const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');

const scoreVal = document.getElementById('scoreVal');
const bestVal = document.getElementById('bestVal');

let highScore = parseInt(localStorage.getItem('ge_high') || '0', 10);
bestVal.textContent = highScore;

// Player state
let player = {
  x: 100,
  y: 280,
  size: 32,
  vy: 0,
  gravity: 0.8,
  jumpStrength: -13,
  grounded: false,
  rotation: 0
};

let obstacles = [];
let score = 0;
let gameSpeed = 6;
let isGameOver = false;
let frameCount = 0;

function resetGame() {
  player.y = 280;
  player.vy = 0;
  player.rotation = 0;
  obstacles = [];
  score = 0;
  gameSpeed = 6;
  isGameOver = false;
  frameCount = 0;
  loop();
}

function jump() {
  if (isGameOver) {
    resetGame();
    return;
  }
  if (player.grounded) {
    player.vy = player.jumpStrength;
    player.grounded = false;
  }
}

window.addEventListener('keydown', (e) => {
  if (e.code === 'Space' || e.code === 'ArrowUp') {
    e.preventDefault();
    jump();
  }
});

canvas.addEventListener('click', () => {
  jump();
});

function spawnObstacle() {
  const type = Math.random() > 0.5 ? 'spike' : 'tall';
  obstacles.push({
    x: canvas.width,
    y: type === 'spike' ? 312 : 272,
    w: 32,
    h: type === 'spike' ? 32 : 72,
    type: type
  });
}

function update() {
  if (isGameOver) return;

  frameCount++;
  score = Math.floor(frameCount / 10);
  scoreVal.textContent = score;

  // Increase speed gradually
  gameSpeed = 6 + Math.floor(score / 50) * 0.5;

  // Apply physics
  player.vy += player.gravity;
  player.y += player.vy;

  // Ground collision
  const groundLevel = 344 - player.size;
  if (player.y >= groundLevel) {
    player.y = groundLevel;
    player.vy = 0;
    player.grounded = true;
    player.rotation = Math.round(player.rotation / 90) * 90; // Snap upright
  } else {
    player.rotation += 8;
  }

  // Spawn obstacles
  if (frameCount % Math.max(70 - Math.floor(score/20), 35) === 0) {
    spawnObstacle();
  }

  // Move and check obstacles
  for (let i = obstacles.length - 1; i >= 0; i--) {
    let obs = obstacles[i];
    obs.x -= gameSpeed;

    // Remove offscreen
    if (obs.x + obs.w < 0) {
      obstacles.splice(i, 1);
      continue;
    }

    // AABB Collision Detection
    if (
      player.x < obs.x + obs.w - 6 &&
      player.x + player.size > obs.x + 6 &&
      player.y < obs.y + obs.h - 4 &&
      player.y + player.size > obs.y + 4
    ) {
      isGameOver = true;
      if (score > highScore) {
        highScore = score;
        localStorage.setItem('ge_high', highScore.toString());
        bestVal.textContent = highScore;
      }
    }
  }
}

function draw() {
  // Clear background
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Draw Ground Grid / Line
  ctx.strokeStyle = '#10b981';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.moveTo(0, 344);
  ctx.lineTo(canvas.width, 344);
  ctx.stroke();

  // Draw Obstacles (Spikes / Blocks)
  obstacles.forEach(obs => {
    ctx.fillStyle = '#ef4444';
    ctx.strokeStyle = '#f87171';
    ctx.lineWidth = 2;

    if (obs.type === 'spike') {
      ctx.beginPath();
      ctx.moveTo(obs.x, obs.y + obs.h);
      ctx.lineTo(obs.x + obs.w / 2, obs.y);
      ctx.lineTo(obs.x + obs.w, obs.y + obs.h);
      ctx.closePath();
      ctx.fill();
      ctx.stroke();
    } else {
      ctx.fillRect(obs.x, obs.y, obs.w, obs.h);
      ctx.strokeRect(obs.x, obs.y, obs.w, obs.h);
    }
  });

  // Draw Player (Rotating Square)
  ctx.save();
  ctx.translate(player.x + player.size / 2, player.y + player.size / 2);
  if (!player.grounded) {
    ctx.rotate((player.rotation * Math.PI) / 180);
  }
  ctx.fillStyle = '#38bdf8';
  ctx.fillRect(-player.size / 2, -player.size / 2, player.size, player.size);
  ctx.strokeStyle = '#bae6fd';
  ctx.lineWidth = 3;
  ctx.strokeRect(-player.size / 2, -player.size / 2, player.size, player.size);
  ctx.restore();

  // Game Over Overlay
  if (isGameOver) {
    ctx.fillStyle = 'rgba(11, 15, 25, 0.85)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.fillStyle = '#f8fafc';
    ctx.font = '900 36px system-ui';
    ctx.textAlign = 'center';
    ctx.fillText('CRASHED!', canvas.width / 2, canvas.height / 2 - 20);

    ctx.fillStyle = '#94a3b8';
    ctx.font = '700 18px system-ui';
    ctx.fillText('Click or press Space to Retry', canvas.width / 2, canvas.height / 2 + 25);
  }
}

function loop() {
  update();
  draw();
  if (!isGameOver) {
    requestAnimationFrame(loop);
  }
}

loop();
